import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
from collections import Counter
def transform(grid):
    h,w=len(grid),len(grid[0])
    # components of same color
    seen=[[False]*w for _ in range(h)]
    out=[row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if seen[i][j]: continue
            c=grid[i][j]; comp=[(i,j)]; seen[i][j]=True; st=[(i,j)]
            while st:
                y,x=st.pop()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx]==c:
                        seen[ny][nx]=True; comp.append((ny,nx)); st.append((ny,nx))
            if len(comp)==1:
                y,x=comp[0]
                nb=[grid[y+dy][x+dx] for dy in(-1,0,1) for dx in(-1,0,1)
                    if (dy or dx) and 0<=y+dy<h and 0<=x+dx<w and grid[y+dy][x+dx]!=c]
                if nb: out[y][x]=Counter(nb).most_common(1)[0][0]
    return out
